INSERT INTO muscle (name, description) VALUES ('adductors', 'The function of the adductor muscles is to pull the thighs together and rotate the upper leg inwards, as well as stabilizing the hip.');
INSERT INTO muscle (name, description) VALUES ('anterior deltoid', 'The anterior deltoid helps move your arm forward. They connect to your clavicle.');
INSERT INTO muscle (name, description) VALUES ('biceps', 'The main functions of the biceps are the flexion and supination (outward rotation) of the forearm.');
INSERT INTO muscle (name, description) VALUES ('calves', 'Your calf muscle supports you when you stand and enables you to move your foot and your lower leg. It propels (pushes) you forward when you walk or run. It also allows you to jump, rotate your ankle, flex your foot and "lock" your knee.');
INSERT INTO muscle (name, description) VALUES ('erector spinae', 'The main actions of the erector spinae muscles are to extend the back, laterally flex the back, and maintain correct posture and curvature of the spinal column.');
INSERT INTO muscle (name, description) VALUES ('glutes', 'Gluteus maximus is the primary hip extensor muscle, and also the largest of the three gluteals. Their biggest job is in keeping us upright and pushing our bodies forward.');
INSERT INTO muscle (name, description) VALUES ('hamstrings', 'Your hamstring muscles serve a variety of functions, including: Bending the knee joint. Extending the hip joint. Rotating the hip joint.');
INSERT INTO muscle (name, description) VALUES ('hip flexors', 'Hip flexors are a group of muscles responsible for flexing the hip and raising the legs. These muscles are essential in movement as you use this muscle group every time you stand or take a step; they also help maintain your stability and posture.');
INSERT INTO muscle (name, description) VALUES ('lateral deltoid', 'The lateral deltoid helps move your arm to the side, as well as up and down. They connect to your acromion, a bony nob on your shoulder blade.');
INSERT INTO muscle (name, description) VALUES ('lats', 'Functionally, the latissimus dorsi muscle belongs to the muscles of the scapular motion. This muscle is able to pull the inferior angle of the scapula in various directions, producing movements on the shoulder joint (internal rotation, adduction and extension of the arm).');
INSERT INTO muscle (name, description) VALUES ('neck', 'You have more than 20 neck muscles, extending from the base of your skull and jaw down to your shoulder blades and collarbone. These muscles support and stabilize your head, neck and the upper part of your spine.');
INSERT INTO muscle (name, description) VALUES ('obliques', 'Rotating and twisting the trunk of the body. Stabilizing the core of the body. Moving the spine in any direction possible. Assisting in bending the trunk from side to side.');
INSERT INTO muscle (name, description) VALUES ('pec major', 'The primary functions are flexion, adduction, and internal rotation of the humerus. The pectoral major may colloquially be referred to as "pecs", "pectoral muscle", or "chest muscle", because it is the largest and most superficial muscle in the chest area.');
INSERT INTO muscle (name, description) VALUES ('pec minor', 'The primary actions of this muscle include the stabilization, depression, abduction or protraction, internal rotation and downward rotation of the scapula.');
INSERT INTO muscle (name, description) VALUES ('quadriceps', 'The main functions of the quadriceps are to extend the leg at the knee joint and flex the thigh at the hip joint. They also help stabilize the knee by holding the patella inside a groove in the femur, or thigh bone.');
INSERT INTO muscle (name, description) VALUES ('rear deltoid', 'The rear deltoid helps move your arm backwards. They connect to the flat surface of your shoulder blade.');
INSERT INTO muscle (name, description) VALUES ('rectus abdominis', 'The main actions of the rectus abdominis are flexion of the trunk (thoratic and lumbar spine), tensing the anterior abdominal wall and compression the contents of the abdomen, and also plays a role in core stability.');
INSERT INTO muscle (name, description) VALUES ('rhomboids', 'Functionally, the rhomboid muscles retract, elevate and rotate the scapula. They also protract the medial border of the scapula, keeping it in position at the posterior thoracic wall.');
INSERT INTO muscle (name, description) VALUES ('rotator cuff', 'During arm movements, the rotator muscles contract and prevent the sliding of the head of the humerus, allowing full range of motion and providing stability. Additionally, rotator cuff muscles help in the mobility of the shoulder joint by facilitating abduction, medial rotation, and lateral rotation.');
INSERT INTO muscle (name, description) VALUES ('serratus anterior', 'When the shoulder girdle is fixed, all three parts of the serratus anterior muscle work together to lift the ribs, assisting with respiration. The serratus anterior, also known as the "boxers muscle", is largely responsible for the protraction of the scapula, a movement that occurs when throwing a punch');
INSERT INTO muscle (name, description) VALUES ('teres major', 'The teres major functions synergistically with the latissimus dorsi to extend, adduct, and internally rotate the humerus.');
INSERT INTO muscle (name, description) VALUES ('teres minor', 'As a rotator cuff muscle, the teres minor stabilizes the ball-and-socket glenohumeral joint by helping hold the humeral head (ball) into the shallow glenoid cavity of the scapula (socket). The teres minor also laterally or externally rotates the arm at the shoulder joint.');
INSERT INTO muscle (name, description) VALUES ('traps', 'The function of the trapezius is to stabilize and move the scapula. The upper fibers can elevate and upwardly rotate the scapula and extend the neck. The middle fibers adduct (medially retract) the scapula. The lower fibers depress and aid the upper fibers in upwardly rotating the scapula.');
INSERT INTO muscle (name, description) VALUES ('triceps', 'The triceps brachii is a large, thick muscle on the dorsal part of the upper arm. It often appears in the shape of a horseshoe on the posterior aspect of the arm. The primary function of the triceps is the extension of the elbow joint.');
INSERT INTO muscle (name, description) VALUES ('upper back', 'The intrinsic muscles of the scapula include the rotator cuff muscles, teres major, subscapularis, teres minor, and infraspinatus. These muscles attach the scapular surface and assist with abduction and external and internal rotation of the glenohumeral joint.');
INSERT INTO equipment (name, description) VALUES ('ab wheel', 'A wheel device with handles on either side.');
INSERT INTO equipment (name, description) VALUES ('adjustable bench', 'A bench whose back pad (and sometimes seat) allows you to change the angle of elevation.');
INSERT INTO equipment (name, description) VALUES ('airex pad', 'An active therapy and training device made out of soft foam.');
INSERT INTO equipment (name, description) VALUES ('bands', 'An elastic band that provides varying levels of resistance, depending on the band itself.');
INSERT INTO equipment (name, description) VALUES ('bench', 'A bench with a foam pad, commonly used for the bench press or other similar exercises.');
INSERT INTO equipment (name, description) VALUES ('box', 'a piece of training equipment used for plyometric exercises requiring jumping or dropping off at certain heights.');
INSERT INTO equipment (name, description) VALUES ('dumbbells', 'Dumbbells are small bars that fit in your hand and have equal weights on either side.');
INSERT INTO equipment (name, description) VALUES ('ghr', 'A specialized piece of equipment used primarily to strengthen the glutes and hamstrings.');
INSERT INTO equipment (name, description) VALUES ('hurdle', 'An upright frame to jump over.');
INSERT INTO equipment (name, description) VALUES ('iron neck', 'A specialized device used to improve strength and mobility in the head, neck, and spine.');
INSERT INTO equipment (name, description) VALUES ('kettlebell', 'A cast-iron or cast-steel ball with a handle attached to the top.');
INSERT INTO equipment (name, description) VALUES ('landmine', 'A barbell anchored to the floor with a weight on the other end.');
INSERT INTO equipment (name, description) VALUES ('med ball', 'A medicine ball is a weighted ball often used for rehabilitation and strength training.');
INSERT INTO equipment (name, description) VALUES ('physioball', 'A ball constructed of soft elastic, and filled with air.');
INSERT INTO equipment (name, description) VALUES ('power bar', 'A universal weightlifting bar that can be used to perform a variety of exercises.');
INSERT INTO equipment (name, description) VALUES ('power rack', 'A piece of weight training equipment that functions as a mechanical spotter for free weight barbell exercises without the movement restrictions imposed by equipment.');
INSERT INTO equipment (name, description) VALUES ('pull-up bar', 'A bar anchored above your head-level that allows you to hang without your feet touching the ground, which can be used to perform a variety of exercises such as pull-ups, chin-ups, and muscle-ups.');
INSERT INTO equipment (name, description) VALUES ('reverse hyper', 'The Reverse Hyper is used for prehab, and rehab, to strengthen the lower back and perform many other exercise variations on it to avoid accommodation.');
INSERT INTO equipment (name, description) VALUES ('safety squat bar', 'A steel-cambered bar with padding in the middle and handles on both sides. The padding makes it comfortable to rest the bar on your neck and shoulders during squats.');
INSERT INTO equipment (name, description) VALUES ('sliders', 'A pair of disks or carpet sliders that provide an unstable training surface, allowing you to simulate many different slideboard exercises');
INSERT INTO equipment (name, description) VALUES ('trap bar', 'A hexagonally-shaped bar with handles inside the hexagon.');
INSERT INTO equipment (name, description) VALUES ('trx', 'The TRX System, also known as Total Resistance Exercises, refers to a specialized form of suspension training.');
